const steps=["<section class=\"card\"><h2>基本信息</h2><div class=\"grid\"><label class=\"field\">中文姓名<input data-qa-key=\"contact.name\" type=\"text\" autocomplete=\"name\"></label><label class=\"field\">电子邮箱<input data-qa-key=\"contact.email\" type=\"text\" ></label><label class=\"field\">手机号码<input data-qa-key=\"contact.phone\" type=\"text\" ></label><label class=\"field\">英文名<input data-qa-key=\"contact.givenName\" type=\"text\" ></label><label class=\"field\">英文姓<input data-qa-key=\"contact.familyName\" type=\"text\" ></label><label class=\"field\">现居省份<select data-qa-key=\"additional.province\" ><option value=\"\">请选择</option><option value=\"zj\">浙江省</option><option value=\"js\">江苏省</option></select></label><label class=\"field\">居住城市<select data-qa-key=\"contact.city\" id=\"city\"><option value=\"\">请选择</option></select></label><label class=\"field\">所在区县<select data-qa-key=\"additional.district\" id=\"district\"><option value=\"\">请选择</option></select></label></div><fieldset><legend>性别</legend><label><input type=\"radio\" name=\"additional.gender\" data-qa-key=\"additional.gender\" value=\"m\">男</label>　<label><input type=\"radio\" name=\"additional.gender\" data-qa-key=\"additional.gender\" value=\"f\">女</label>　</fieldset><label class=\"field\">政治面貌<select data-qa-key=\"additional.politicalStatus\" ><option value=\"\">请选择</option><option value=\"party\">中共党员</option><option value=\"none\">群众</option></select></label></section>","<section class=\"card\"><h2>教育经历</h2><div id=\"education-rows\"><fieldset class=\"experience-row\"><legend>教育经历 1</legend><div class=\"grid\"><label class=\"field\">院校名称<input data-qa-key=\"education.0.school\" type=\"text\" ></label><label class=\"field\">专业<input data-qa-key=\"education.0.major\" type=\"text\" ></label><label class=\"field\">学历<select data-qa-key=\"education.0.degree\" ><option value=\"\">请选择</option><option value=\"bs\">本科</option><option value=\"ms\">硕士</option><option value=\"phd\">博士</option></select></label><label class=\"field\">入学时间<input data-qa-key=\"education.0.startDate\" type=\"month\" ></label><label class=\"field\">毕业时间<input data-qa-key=\"education.0.endDate\" type=\"month\" ></label></div></fieldset></div><button type=\"button\" id=\"add-edu\">新增教育经历</button></section><section class=\"card\"><h2>实习经历</h2><table><thead><tr><th>单位名称</th><th>职位名称</th><th>开始日期</th><th>结束日期</th><th>经历描述</th></tr></thead><tbody><tr><td><input data-qa-key=\"internships.0.organization\" aria-label=\"单位名称\" type=\"text\"></td><td><input data-qa-key=\"internships.0.title\" aria-label=\"职位名称\" type=\"text\"></td><td><input data-qa-key=\"internships.0.startDate\" aria-label=\"开始日期\" type=\"date\"></td><td><input data-qa-key=\"internships.0.endDate\" aria-label=\"结束日期\" type=\"date\"></td><td><input data-qa-key=\"internships.0.description\" aria-label=\"经历描述\" type=\"text\"></td></tr><tr><td><input data-qa-key=\"internships.1.organization\" aria-label=\"单位名称\" type=\"text\"></td><td><input data-qa-key=\"internships.1.title\" aria-label=\"职位名称\" type=\"text\"></td><td><input data-qa-key=\"internships.1.startDate\" aria-label=\"开始日期\" type=\"date\"></td><td><input data-qa-key=\"internships.1.endDate\" aria-label=\"结束日期\" type=\"date\"></td><td><input data-qa-key=\"internships.1.description\" aria-label=\"经历描述\" type=\"text\"></td></tr></tbody></table></section>","<fieldset><legend>项目经历 1</legend><div class=\"grid\"><label class=\"field\">项目名称<input data-qa-key=\"projects.0.name\" type=\"text\" ></label><label class=\"field\">担任角色<input data-qa-key=\"projects.0.role\" type=\"text\" ></label><label class=\"field\">开始日期<input data-qa-key=\"projects.0.startDate\" type=\"date\" ></label><label class=\"field\">结束日期<input data-qa-key=\"projects.0.endDate\" type=\"date\" ></label><label class=\"field\">项目描述<textarea data-qa-key=\"projects.0.description\"></textarea></label></div></fieldset><fieldset><legend>项目经历 2</legend><div class=\"grid\"><label class=\"field\">项目名称<input data-qa-key=\"projects.1.name\" type=\"text\" ></label><label class=\"field\">担任角色<input data-qa-key=\"projects.1.role\" type=\"text\" ></label><label class=\"field\">开始日期<input data-qa-key=\"projects.1.startDate\" type=\"date\" ></label><label class=\"field\">结束日期<input data-qa-key=\"projects.1.endDate\" type=\"date\" ></label><label class=\"field\">项目描述<textarea data-qa-key=\"projects.1.description\"></textarea></label></div></fieldset><fieldset><legend>证书 1</legend><div class=\"grid\"><label class=\"field\">证书名称<input data-qa-key=\"certificates.0.name\" type=\"text\" ></label><label class=\"field\">颁发机构<input data-qa-key=\"certificates.0.issuer\" type=\"text\" ></label><label class=\"field\">获得时间<input data-qa-key=\"certificates.0.date\" type=\"date\" ></label></div></fieldset><fieldset><legend>证书 2</legend><div class=\"grid\"><label class=\"field\">证书名称<input data-qa-key=\"certificates.1.name\" type=\"text\" ></label><label class=\"field\">颁发机构<input data-qa-key=\"certificates.1.issuer\" type=\"text\" ></label><label class=\"field\">获得时间<input data-qa-key=\"certificates.1.date\" type=\"date\" ></label></div></fieldset><fieldset><legend>技能</legend><label class=\"field\">专业技能<select data-qa-key=\"skills.all\" multiple size=\"4\"><option value=\"\">请选择</option><option value=\"JavaScript\">JavaScript</option><option value=\"SQL\">SQL</option><option value=\"Java\">Java</option></select></label></fieldset><label><input data-qa-key=\"protected.declaration\" type=\"checkbox\">本人声明以上信息真实，确认提交</label>"];const edu="<fieldset class=\"experience-row\"><legend>教育经历 2</legend><div class=\"grid\"><label class=\"field\">院校名称<input data-qa-key=\"education.1.school\" type=\"text\" ></label><label class=\"field\">专业<input data-qa-key=\"education.1.major\" type=\"text\" ></label><label class=\"field\">学历<select data-qa-key=\"education.1.degree\" ><option value=\"\">请选择</option><option value=\"bs\">本科</option><option value=\"ms\">硕士</option><option value=\"phd\">博士</option></select></label><label class=\"field\">入学时间<input data-qa-key=\"education.1.startDate\" type=\"month\" ></label><label class=\"field\">毕业时间<input data-qa-key=\"education.1.endDate\" type=\"month\" ></label></div></fieldset>";let step=Number(new URLSearchParams(location.search).get('step')||1);document.querySelector('#step-label').textContent='当前第 '+step+' / 3 步';document.querySelector('#wizard').innerHTML=steps[step-1]+(step<3?'<button type="button" id="next">保存并进入下一步</button>':'<button type="submit" class="danger">模拟提交（验收禁止点击）</button>')+'<button type="button" id="view-all">查看已保存结果</button>';document.querySelector('#next')?.addEventListener('click',()=>{sessionStorage.setItem('soe-step-'+step,JSON.stringify(window.qaRead()));location.href='soe.html?step='+(step+1)});document.querySelector('#add-edu')?.addEventListener('click',()=>{if(!document.querySelector('[data-qa-key="education.1.school"]'))document.querySelector('#education-rows').insertAdjacentHTML('beforeend',edu)});document.querySelector('[data-qa-key="additional.province"]')?.addEventListener('change',()=>setTimeout(()=>{document.querySelector('#city').innerHTML='<option value="">请选择</option><option value="hz">杭州</option><option value="nb">宁波</option>'},600));document.querySelector('#city')?.addEventListener('change',()=>setTimeout(()=>{document.querySelector('#district').innerHTML='<option value="">请选择</option><option value="xh">西湖区</option><option value="sc">上城区</option>'},500));document.querySelector('#view-all').addEventListener('click',()=>{const pre=document.createElement('pre');pre.id='all-results';pre.textContent=JSON.stringify({step1:JSON.parse(sessionStorage.getItem('soe-step-1')||'{}'),step2:JSON.parse(sessionStorage.getItem('soe-step-2')||'{}'),step3:window.qaRead()},null,2);document.querySelector('main').append(pre)});